alter table recipes add column if not exists real_time boolean not null default false;

values ('garlic-butter-pasta', 'Garlic Butter Pasta', 'Glossy, emulsified butter sauce built from pasta water. The first sauce every cook should own.', 'Be a Chef Kitchen', 'Pasta', array['vegetarian']::text[], 2, 'saffron', 'https://www.themealdb.com/images/media/meals/uquqtu1511178042.jpg/medium', false, '[{"id":"spaghetti","name":"Spaghetti","quantity":200,"unit":"g"},{"id":"garlic","name":"Garlic","quantity":4,"unit":"pc","prep":"thinly sliced"},{"id":"butter","name":"Unsalted butter","quantity":50,"unit":"g","prep":"cubed, cold"},{"id":"parsley","name":"Parsley","quantity":2,"unit":"tbsp","prep":"chopped"},{"id":"lemon","name":"Lemon","quantity":0.5,"unit":"pc"}]'::jsonb, false)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, chef = excluded.chef, category = excluded.category, dietary = excluded.dietary, serves = excluded.serves, colourway = excluded.colourway, image_url = excluded.image_url, premium = excluded.premium, ingredients = excluded.ingredients, real_time = excluded.real_time;
delete from recipe_blocks where recipe_slug = 'garlic-butter-pasta';

