insert into recipes (slug, title, summary, chef, category, dietary, serves, colourway, image_url, premium, ingredients, real_time)
insert into recipe_blocks (recipe_slug, position, id, kind, body) values
  ('garlic-butter-pasta', 0, 'boil', 'heat', '{"heat":"high","vessel":"large pot","text":"Bring 2 litres of water to a rolling boil, then salt it generously.","minutes":8,"attention":"passive","cue":"big bubbles break the surface constantly","science":"Salt at ~1% by weight seasons the pasta from within; it doesn''t meaningfully raise the boiling point.","terms":{"rolling boil":"bubbles that keep going even when you stir"}}'::jsonb),
  ('garlic-butter-pasta', 1, 'prep', 'prep', '{"ingredientIds":["garlic","parsley","butter"],"text":"Slice the garlic thinly, chop the parsley and cube the butter. Keep the butter cold.","minutes":4,"attention":"active","science":"Cold butter emulsifies more slowly and stably than melted butter."}'::jsonb),
  ('garlic-butter-pasta', 2, 'cook-pasta', 'timing', '{"timerLabel":"Pasta","text":"Cook the spaghetti 1 minute short of the packet time, then reserve a mug of pasta water.","minutes":9,"attention":"passive","cue":"it bends but still has a thin white core when bitten","science":"Pulling it early lets it finish in the sauce and absorb flavour; the starchy water is your emulsifier.","terms":{"al dente":"cooked but still firm to the bite"}}'::jsonb),
  ('garlic-butter-pasta', 3, 'garlic', 'heat', '{"heat":"medium-low","vessel":"wide frying pan","text":"Warm 1 tbsp of the butter, add the garlic and cook gently.","minutes":2,"attention":"active","cue":"the garlic is pale gold and smells sweet, not brown","science":"Garlic burns above ~160 °C; low heat extracts sweetness before the Maillard browning turns bitter."}'::jsonb),
  ('garlic-butter-pasta', 4, 'emulsify', 'heat', '{"heat":"medium","vessel":"wide frying pan","text":"Add the pasta and a splash of pasta water, then toss while adding the cold butter a cube at a time; finish with lemon and parsley.","minutes":2,"attention":"active","cue":"the sauce looks creamy and clings to the pasta","science":"Starch stabilises the butterfat in water; keep it below a simmer or the emulsion breaks.","terms":{"emulsify":"blend fat and water into one smooth sauce"}}'::jsonb);
insert into recipes (slug, title, summary, chef, category, dietary, serves, colourway, image_url, premium, ingredients, real_time)
insert into recipe_blocks (recipe_slug, position, id, kind, body) values
  ('crispy-chickpea-traybake', 0, 'oven', 'heat', '{"heat":"high","vessel":"oven at 220 °C / 200 °C fan","text":"Heat the oven with the empty tray inside.","minutes":10,"attention":"passive","science":"A preheated tray sears on contact, so the chickpeas crisp instead of steaming."}'::jsonb),
  ('crispy-chickpea-traybake', 1, 'prep', 'prep', '{"ingredientIds":["chickpeas","pepper","onion","paprika","oil"],"text":"Pat the chickpeas very dry, then toss everything with the oil, paprika and a pinch of salt.","minutes":6,"attention":"active","cue":"every chickpea is lightly coated and there''s no water pooling","terms":{"pat dry":"press gently with a clean towel to remove surface water"}}'::jsonb),
  ('crispy-chickpea-traybake', 2, 'roast', 'timing', '{"timerLabel":"Roast","text":"Spread on the hot tray in one layer and roast, shaking once halfway.","minutes":25,"attention":"passive","cue":"the peppers have black blisters and the chickpeas rattle when shaken","science":"One layer matters: crowding traps steam and drops the surface temperature below browning."}'::jsonb);
insert into recipes (slug, title, summary, chef, category, dietary, serves, colourway, image_url, premium, ingredients, real_time)
insert into recipe_blocks (recipe_slug, position, id, kind, body) values
  ('pan-seared-salmon', 0, 'dry', 'prep', '{"ingredientIds":["salmon"],"text":"Pat the skin completely dry and salt it; leave it for 5 minutes.","minutes":5,"attention":"passive","science":"Salt draws out surface moisture you can blot again; dry skin is what makes crisp skin."}'::jsonb),
  ('pan-seared-salmon', 1, 'sear', 'heat', '{"heat":"medium-high","vessel":"heavy frying pan","text":"Heat the oil until shimmering, lay the salmon skin-side down and press for 10 seconds; cook without moving it.","minutes":5,"attention":"active","cue":"the colour has crept two-thirds of the way up the side","science":"Pressing stops the skin buckling as proteins contract, keeping full contact for even browning.","terms":{"shimmering":"the oil ripples like a heat haze, just before it smokes"}}'::jsonb),
  ('pan-seared-salmon', 2, 'baste', 'heat', '{"heat":"medium","vessel":"heavy frying pan","text":"Flip, add the butter and thyme, then spoon the foaming butter over the fish.","minutes":1.5,"attention":"active","cue":"the butter smells nutty and turns light brown","science":"Foaming butter is past 100 °C; basting cooks the top gently while milk solids brown for flavour.","terms":{"baste":"spoon hot fat over food while it cooks"}}'::jsonb),
  ('pan-seared-salmon', 3, 'rest', 'timing', '{"timerLabel":"Rest","text":"Rest skin-side up for 2 minutes.","minutes":2,"attention":"passive","science":"Carry-over cooking adds ~3 °C; aim to pull at 45–50 °C in the centre for a moist finish."}'::jsonb);
insert into recipes (slug, title, summary, chef, category, dietary, serves, colourway, image_url, premium, ingredients, real_time)
insert into recipe_blocks (recipe_slug, position, id, kind, body) values
  ('fluffy-rice', 0, 'rinse', 'prep', '{"ingredientIds":["rice"],"text":"Rinse the rice in a sieve until the water runs almost clear.","minutes":2,"attention":"active","science":"Rinsing removes loose surface starch that would otherwise glue the grains together."}'::jsonb),
  ('fluffy-rice', 1, 'simmer', 'heat', '{"heat":"low","vessel":"small pot with a tight lid","text":"Bring the rice and water to a boil, then cover and turn to the lowest heat.","minutes":12,"attention":"passive","cue":"small holes appear on the surface and no water is visible","science":"A 1:1.5 ratio by volume for rinsed basmati; the lid traps steam to finish cooking evenly.","terms":{"simmer":"small, gentle bubbles, not a boil"}}'::jsonb),
  ('fluffy-rice', 2, 'rest', 'timing', '{"timerLabel":"Rice rest","text":"Take off the heat and leave covered for 10 minutes, then fluff with a fork.","minutes":10,"attention":"passive","science":"Resting redistributes moisture so the bottom isn''t wet and the top isn''t firm."}'::jsonb);
insert into recipes (slug, title, summary, chef, category, dietary, serves, colourway, image_url, premium, ingredients, real_time)
insert into recipe_blocks (recipe_slug, position, id, kind, body) values
  ('broccoli-chilli-pasta', 0, 'water', 'heat', '{"heat":"high","vessel":"large pot with a lid","text":"Before anything else, fill a large pot with water, cover it and put it on high heat. It comes to the boil while you prep.","minutes":1,"attention":"active","science":"A lid traps the heat that would escape as steam, so the water boils several minutes sooner."}'::jsonb),
  ('broccoli-chilli-pasta', 1, 'cut-broccoli', 'prep', '{"ingredientIds":["broccoli"],"text":"Cut the broccoli into small florets and slice the tender stalk into thin coins. Nothing goes in the bin.","minutes":5,"attention":"active","cue":"the florets are about the size of a grape"}'::jsonb),
  ('broccoli-chilli-pasta', 2, 'prep-rest', 'prep', '{"ingredientIds":["garlic","parmesan","lemon"],"text":"Thinly slice the garlic, grate the Parmesan and halve the lemon. When the water boils, salt it well.","minutes":3,"attention":"active","terms":{"salt it well":"about 1 tablespoon of salt for a large pot; it should taste pleasantly salty"}}'::jsonb),
  ('broccoli-chilli-pasta', 3, 'boil', 'timing', '{"timerLabel":"Pasta","text":"Add the pasta and set a timer for the packet time. Drop the broccoli in for the last 4 minutes.","minutes":10,"attention":"passive","cue":"the pasta is tender with a little bite and the broccoli is bright green","science":"Cooking both in one salted pot seasons the broccoli and saves a pan.","terms":{"al dente":"cooked but still slightly firm in the middle"}}'::jsonb),
  ('broccoli-chilli-pasta', 4, 'chilli-oil', 'heat', '{"heat":"medium-low","vessel":"wide frying pan","during":"boil","text":"While the pasta boils, warm the oil, garlic and chilli flakes in a wide pan. Take it off the heat once the garlic turns pale gold.","minutes":4,"attention":"active","cue":"the garlic is pale gold and smells sweet","science":"Starting garlic in cool oil lets it soften and sweeten; dropped into hot oil it scorches and turns bitter."}'::jsonb),
  ('broccoli-chilli-pasta', 5, 'rinse-board', 'prep', '{"ingredientIds":[],"during":"boil","text":"Still waiting on the pasta? Rinse the board and knife now so they''re done before you eat.","minutes":2,"attention":"active"}'::jsonb),
  ('broccoli-chilli-pasta', 6, 'toss', 'heat', '{"heat":"medium","vessel":"wide frying pan","text":"Scoop out a mug of pasta water, drain, then toss the pasta and broccoli in the chilli oil with a splash of the water, the Parmesan and a squeeze of lemon.","minutes":2,"attention":"active","cue":"the sauce is glossy and coats the pasta instead of pooling","science":"Starch in the pasta water binds the oil and cheese into a light sauce."}'::jsonb);
insert into recipes (slug, title, summary, chef, category, dietary, serves, colourway, image_url, premium, ingredients, real_time)
insert into recipe_blocks (recipe_slug, position, id, kind, body) values
  ('chickpea-spinach-curry-rice', 0, 'rice-on', 'heat', '{"heat":"high","vessel":"small pot with a tight lid","text":"Rinse the rice, put it in a pot with 300 ml water and a pinch of salt, and bring to the boil.","minutes":3,"attention":"active","science":"Rinsing washes off loose starch so the grains stay separate."}'::jsonb),
  ('chickpea-spinach-curry-rice', 1, 'rice-cook', 'timing', '{"timerLabel":"Rice","text":"Cover, turn the heat right down and set a 12-minute timer. Leave it alone: the rice is now cooking itself.","minutes":12,"attention":"passive","cue":"small holes appear on top and no water is left","terms":{"absorption method":"cooking rice in just enough water that it soaks it all up"}}'::jsonb),
  ('chickpea-spinach-curry-rice', 2, 'chop', 'prep', '{"ingredientIds":["onion","garlic","ginger"],"during":"rice-cook","text":"While the rice cooks, chop the onion. Peel the garlic and ginger, pile them together and chop them as one.","minutes":4,"attention":"active","terms":{"chop as one":"chopping things that go in the pan together in one pile saves time"}}'::jsonb),
  ('chickpea-spinach-curry-rice', 3, 'fry', 'heat', '{"heat":"medium","vessel":"large frying pan or wide pot","during":"rice-cook","text":"Fry the onion in the oil until soft, then stir in the garlic, ginger and curry powder for 1 minute.","minutes":6,"attention":"active","cue":"the onion is soft and see-through and the spices smell toasty","science":"Spices release most of their flavour into hot oil, so frying them briefly beats adding them to liquid."}'::jsonb),
  ('chickpea-spinach-curry-rice', 4, 'simmer', 'timing', '{"timerLabel":"Curry","text":"Add the tomatoes, chickpeas and coconut milk, season and simmer. Meanwhile take the rice off the heat and keep it covered.","minutes":8,"attention":"passive","cue":"the sauce has thickened enough to coat a spoon","terms":{"simmer":"small, lazy bubbles rather than a rolling boil"}}'::jsonb),
  ('chickpea-spinach-curry-rice', 5, 'wash-up', 'prep', '{"ingredientIds":[],"during":"simmer","text":"While the curry simmers, wash the board and wipe the counter.","minutes":3,"attention":"active"}'::jsonb),
  ('chickpea-spinach-curry-rice', 6, 'spinach', 'heat', '{"heat":"medium","vessel":"large frying pan or wide pot","text":"Stir in the spinach a handful at a time until it wilts. Fluff the rice with a fork and serve.","minutes":2,"attention":"active","cue":"the spinach has just collapsed and is still bright green"}'::jsonb);
insert into recipes (slug, title, summary, chef, category, dietary, serves, colourway, image_url, premium, ingredients, real_time)
insert into recipe_blocks (recipe_slug, position, id, kind, body) values
  ('sausage-potato-green-bean-traybake', 0, 'oven', 'heat', '{"heat":"high","vessel":"oven at 220 °C / 200 °C fan","text":"Turn the oven on first and slide in a large tray with the oil on it to heat up.","minutes":1,"attention":"active","science":"Oil already hot in the tray sears the potatoes the moment they land, so they brown instead of sticking."}'::jsonb),
  ('sausage-potato-green-bean-traybake', 1, 'cut', 'prep', '{"ingredientIds":["potatoes"],"text":"Halve the potatoes (quarter any big ones) while the oven heats.","minutes":5,"attention":"active","cue":"the pieces are roughly the same size so they cook evenly"}'::jsonb),
  ('sausage-potato-green-bean-traybake', 2, 'roast-potatoes', 'timing', '{"timerLabel":"Potatoes","text":"Tip the potatoes into the hot tray, season, toss and roast. You don''t need to wait for the oven to be fully hot.","minutes":15,"attention":"passive","cue":"the cut sides have started to colour"}'::jsonb),
  ('sausage-potato-green-bean-traybake', 3, 'trim', 'prep', '{"ingredientIds":["beans","mustard","honey"],"during":"roast-potatoes","text":"While the potatoes roast, trim the beans and stir the mustard and honey together in a small bowl.","minutes":4,"attention":"active"}'::jsonb),
  ('sausage-potato-green-bean-traybake', 4, 'roast-all', 'timing', '{"timerLabel":"Traybake","text":"Add the sausages and beans to the tray, turn everything in the oil and roast until the sausages are browned and cooked through.","minutes":18,"attention":"passive","cue":"the sausages are golden all over and firm when pressed","science":"Sausages are safe when the centre reaches 72 °C; a quick-read thermometer takes the guesswork out."}'::jsonb),
  ('sausage-potato-green-bean-traybake', 5, 'tidy', 'prep', '{"ingredientIds":[],"during":"roast-all","text":"Use the oven time to wash the knife, board and bowl and lay the table.","minutes":5,"attention":"active"}'::jsonb),
  ('sausage-potato-green-bean-traybake', 6, 'glaze', 'heat', '{"heat":"medium","vessel":"the hot tray, out of the oven","text":"Drizzle the honey mustard over the tray, toss and serve straight from it.","minutes":1,"attention":"active"}'::jsonb);
insert into recipes (slug, title, summary, chef, category, dietary, serves, colourway, image_url, premium, ingredients, real_time)
insert into recipe_blocks (recipe_slug, position, id, kind, body) values
  ('salmon-herby-couscous', 0, 'oven-kettle', 'heat', '{"heat":"high","vessel":"oven at 220 °C / 200 °C fan, and the kettle","text":"Turn the oven on and boil the kettle at the same time.","minutes":1,"attention":"active"}'::jsonb),
  ('salmon-herby-couscous', 1, 'couscous', 'timing', '{"timerLabel":"Couscous","text":"Pour 200 ml boiling stock or water over the couscous with a pinch of salt and a little oil, cover with a plate and leave it.","minutes":10,"attention":"passive","cue":"all the liquid has disappeared and the grains are soft","terms":{"steep":"leave something to soak in hot liquid until it softens"}}'::jsonb),
  ('salmon-herby-couscous', 2, 'salmon-tray', 'prep', '{"ingredientIds":["salmon","oil"],"during":"couscous","text":"While the couscous steeps, put the salmon on a lined tray, rub with oil and season.","minutes":2,"attention":"active"}'::jsonb),
  ('salmon-herby-couscous', 3, 'roast', 'timing', '{"timerLabel":"Salmon","text":"Roast the salmon. It goes in even if the oven isn''t fully hot yet; judge it by look, not the clock.","minutes":10,"attention":"passive","cue":"the flesh flakes when nudged and is just opaque in the middle","science":"Salmon is juiciest pulled at about 50 °C in the centre; it keeps cooking for a minute on the tray."}'::jsonb),
  ('salmon-herby-couscous', 4, 'sauce', 'prep', '{"ingredientIds":["herbs","lemon","yogurt"],"during":"roast","text":"While the salmon roasts, chop the herbs. Stir half into the yogurt with lemon zest, a squeeze of juice and salt.","minutes":4,"attention":"active"}'::jsonb),
  ('salmon-herby-couscous', 5, 'fluff', 'prep', '{"ingredientIds":["couscous","herbs","lemon"],"during":"roast","text":"Fluff the couscous with a fork and fold in the rest of the herbs and a squeeze of lemon.","minutes":2,"attention":"active","cue":"the grains are loose, with no clumps"}'::jsonb),
  ('salmon-herby-couscous', 6, 'serve', 'prep', '{"ingredientIds":[],"text":"Pile the couscous on plates, top with the salmon and spoon over the yogurt sauce.","minutes":1,"attention":"active"}'::jsonb);
insert into recipes (slug, title, summary, chef, category, dietary, serves, colourway, image_url, premium, ingredients, real_time)
insert into recipe_blocks (recipe_slug, position, id, kind, body) values
  ('black-bean-quesadillas-salsa', 0, 'pan', 'heat', '{"heat":"medium","vessel":"large dry frying pan","text":"Put a large dry frying pan on medium heat so it''s hot when you need it.","minutes":1,"attention":"active"}'::jsonb),
  ('black-bean-quesadillas-salsa', 1, 'filling', 'prep', '{"ingredientIds":["beans","cumin","cheese"],"text":"Roughly mash the beans with the cumin and a pinch of salt, and grate the cheese.","minutes":4,"attention":"active","cue":"the beans are half mashed, half whole"}'::jsonb),
  ('black-bean-quesadillas-salsa', 2, 'first', 'timing', '{"timerLabel":"Quesadilla 1","text":"Spread half the beans and cheese over one half of a tortilla, fold it and cook, turning once.","minutes":5,"attention":"passive","cue":"both sides are spotted brown and the cheese has melted"}'::jsonb),
  ('black-bean-quesadillas-salsa', 3, 'salsa', 'prep', '{"ingredientIds":["tomatoes","onion","lime"],"during":"first","text":"While it cooks, chop the tomatoes and onion finely and mix with lime juice and salt.","minutes":4,"attention":"active","terms":{"salsa":"here, a fresh uncooked mix of chopped tomato, onion and lime"}}'::jsonb),
  ('black-bean-quesadillas-salsa', 4, 'second', 'timing', '{"timerLabel":"Quesadilla 2","text":"Build and cook the second quesadilla the same way. Keep the first warm on a plate under a clean towel.","minutes":5,"attention":"passive","cue":"both sides are spotted brown and the cheese has melted"}'::jsonb),
  ('black-bean-quesadillas-salsa', 5, 'serve', 'prep', '{"ingredientIds":["lime"],"during":"second","text":"Cut the first quesadilla into wedges and put the salsa and lime wedges on the table.","minutes":2,"attention":"active"}'::jsonb);
insert into recipes (slug, title, summary, chef, category, dietary, serves, colourway, image_url, premium, ingredients, real_time)
insert into recipe_blocks (recipe_slug, position, id, kind, body) values
  ('apple-cinnamon-porridge', 0, 'oats-on', 'heat', '{"heat":"medium","vessel":"small saucepan","text":"Put the oats, milk and a pinch of salt in a pan over medium heat.","minutes":1,"attention":"active"}'::jsonb),
  ('apple-cinnamon-porridge', 1, 'simmer', 'timing', '{"timerLabel":"Porridge","text":"Simmer, stirring every minute or so, until thick and creamy.","minutes":8,"attention":"passive","cue":"a spoon dragged through leaves a trail that slowly closes","science":"Stirring rubs starch off the oats, which is what makes porridge creamy rather than watery."}'::jsonb),
  ('apple-cinnamon-porridge', 2, 'apple', 'prep', '{"ingredientIds":["apple"],"during":"simmer","text":"Between stirs, core the apple and cut it into small chunks. No need to peel.","minutes":2,"attention":"active"}'::jsonb),
  ('apple-cinnamon-porridge', 3, 'fry-apple', 'heat', '{"heat":"medium-high","vessel":"small frying pan","during":"simmer","text":"Melt the butter in a small frying pan, add the apple, cinnamon and sugar and cook, tossing now and then.","minutes":5,"attention":"active","cue":"the apple is golden at the edges and just tender","science":"The sugar and butter caramelise on the apple''s surface while the inside softens."}'::jsonb),
  ('apple-cinnamon-porridge', 4, 'serve', 'prep', '{"ingredientIds":[],"text":"Spoon the porridge into bowls and pile the apples and their buttery juices on top.","minutes":1,"attention":"active"}'::jsonb);
